+<?php
+
+namespace App\Http\Controllers\Staff;
+
+use App\Enums\AppointmentStatus;
+use App\Http\Controllers\Controller;
+use App\Models\Appointment;
+use Illuminate\Http\RedirectResponse;
+use Illuminate\Http\Request;
+use Illuminate\View\View;
+
+class AppointmentController extends Controller
+{
+    /**
+     * Display a listing of appointments for staff/counselors.
+     */
+    public function index(Request $request): View
+    {
+        $query = Appointment::with(['student', 'counselor']);
+
+        // Filter by status if provided
+        if ($request->has('status') && $request->status !== '') {
+            $query->where('status', $request->status);
+        }
+
+        $appointments = $query->orderBy('scheduled_at', 'asc')->paginate(15);
+
+        return view('staff.appointments.index', compact('appointments'));
+    }
+
+    /**
+     * Update appointment status (Approve, Reject, Complete).
+     */
+    public function update(Request $request, Appointment $appointment): RedirectResponse
+    {
+        $validated = $request->validate([
+            'status' => ['required', 'in:approved,rejected,completed'],
+            'rejection_reason' => ['required_if:status,rejected', 'nullable', 'string', 'max:500'],
+        ]);
+
+        $appointment->update([
+            'status' => $validated['status'],
+            'counselor_id' => $appointment->counselor_id ?? $request->user()->id,
+            'rejection_reason' => $validated['status'] === 'rejected' ? $validated['rejection_reason'] : null,
+        ]);
+
+        return back()->with('status', 'Appointment status updated to ' . ucfirst($validated['status']) . '.');
+    }
+}
